//! Native FPP (False Positive Probability) — port of the production
//! `worker/fpp_native.py` (Giacalone & Dressing 2020 reimplementation).
//!
//! Parity contract: bit-exact (f64-identical) against the Python CPU/numba
//! reference seeded with the deterministic per-TIC seed. Fixtures live in
//! `fixtures/fpp/` and are generated by `parity/fpp/` (see its README for
//! the reference environment and the seed formula).
//!
//! Spec: repo exonit `docs/superpowers/specs/2026-08-17-fpp-rust-port-design.md`.

pub mod fold;
pub mod inputs;
pub mod kernels;
pub mod npsum;
pub mod priors;
pub mod rng;
pub mod scenarios;
pub mod stellar;
pub mod transit;

use crate::fpp_policy::{self, FppVerdict};
use fold::{phase_fold_bin, renorm_flux};
use inputs::{compute_flux_ratios, load_trilegal, parse_nearby};
use npsum::{np_std, pairwise_sum};
use rng::FppRng;
use scenarios::{lnz_peb, lnz_ptp, lnz_teb, lnz_ttp, Probes, StarParams, G_CGS, MSUN, RSUN};

/// Frozen inputs for one FPP evaluation (mirrors `calc_fpp_native` args;
/// the nearby payload is the raw `/api/nearby` JSON).
pub struct FppInputs {
    pub tic_id: String,
    pub period: f64,
    pub t0: f64,
    pub duration: f64,
    pub depth_ppm: f64,
    pub time: Vec<f64>,
    pub flux: Vec<f64>,
    pub nearby_raw: serde_json::Value,
    pub trilegal_csv: Option<String>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct FppResult {
    pub fpp: f64,
    pub nfpp: f64,
    pub verdict: FppVerdict,
    pub high_crowding: bool,
    pub gal_b: f64,
    pub n_nearby: usize,
    pub trilegal_used: bool,
}

/// Checkpoint recorder mirroring the Python golden generator's wrappers.
#[derive(Default, Debug)]
pub struct CalcProbes {
    pub scen: Probes,
    pub phase_fold: Option<(Vec<f64>, Vec<f64>)>,
    /// (ID, fluxratio, tdepth) per star, post `compute_flux_ratios`.
    pub flux_ratios: Vec<(String, f64, f64)>,
    /// (fluxratio, sigma_in, first-8 renormed flux) per `renorm_flux` call.
    pub renorm: Vec<(f64, f64, Vec<f64>)>,
}

/// `calc_fpp_native` (`worker/fpp_native.py:1155-1376`), CPU path, with
/// the deterministic seed replacing the unseeded global RNG.
pub fn calc_fpp(
    inputs: &FppInputs,
    n_draws: usize,
    seed: u32,
    probes: &mut CalcProbes,
) -> Option<FppResult> {
    let (time_pf_raw, flux_pf_raw) =
        phase_fold_bin(&inputs.time, &inputs.flux, inputs.period, inputs.t0, 1000);
    probes.phase_fold = Some((time_pf_raw.clone(), flux_pf_raw.clone()));
    if time_pf_raw.len() < 10 {
        return None;
    }
    let mut time_pf = Vec::with_capacity(time_pf_raw.len());
    let mut flux_pf = Vec::with_capacity(flux_pf_raw.len());
    for (&t, &f) in time_pf_raw.iter().zip(flux_pf_raw.iter()) {
        if !t.is_nan() && !f.is_nan() {
            time_pf.push(t);
            flux_pf.push(f);
        }
    }
    let mut sigma = np_std(&flux_pf);
    if sigma <= 0.0 {
        sigma = 1e-6;
    }

    let nearby = parse_nearby(&inputs.nearby_raw, &inputs.tic_id)?;
    let gal_b = nearby.gal_b;
    let mut stars = nearby.stars;
    if stars.is_empty() {
        return None;
    }
    let n_nearby = stars.len() - 1;
    let high_crowding = gal_b.abs() < 10.0 || n_nearby > 15;

    let trilegal_stars = match &inputs.trilegal_csv {
        Some(csv) => load_trilegal(csv, stars[0].ra, stars[0].dec, stars[0].tmag),
        None => Vec::new(),
    };
    let trilegal_used = !trilegal_stars.is_empty();
    stars.extend(trilegal_stars);

    compute_flux_ratios(&mut stars, inputs.depth_ppm);
    probes.flux_ratios = stars
        .iter()
        .map(|s| (s.id.clone(), s.fluxratio, s.tdepth))
        .collect();

    let target = &stars[0];
    let (m_s, r_s, teff, plx) = (target.mass, target.rad, target.teff, target.plx);
    if m_s.is_nan() || r_s.is_nan() || teff.is_nan() {
        return None;
    }

    // Python-scalar `(R_s*Rsun)**2` → libm pow (see npsum::libm_pow).
    let logg = (G_CGS * m_s * MSUN / npsum::libm_pow(r_s * RSUN, 2.0)).log10();
    let (u1, u2) = stellar::get_ldc(teff, logg, 0.0);

    let target_fr = target.fluxratio;
    let (flux_t, sigma_t) = renorm_flux(&flux_pf, sigma, target_fr);
    probes
        .renorm
        .push((target_fr, sigma, flux_t.iter().copied().take(8).collect()));

    let p_orb = inputs.period;
    let star = StarParams { m_s, r_s, teff };
    let mut rng = FppRng::new(seed);
    let pr = &mut probes.scen;

    let lnz_tp = lnz_ttp(
        &mut rng,
        pr,
        &time_pf,
        &flux_t,
        sigma_t,
        p_orb,
        &star,
        n_draws,
        u1,
        u2,
        0.0,
        false,
        Some("_lnZ_TTP"),
    );
    let (lnz_eb, lnz_ebx2) = lnz_teb(
        &mut rng,
        pr,
        &time_pf,
        &flux_t,
        sigma_t,
        p_orb,
        &star,
        n_draws,
        u1,
        u2,
        0.0,
        false,
        Some("_lnZ_TEB"),
    );

    let (lnz_ptp_v, lnz_peb_v, lnz_pebx2_v) = if !plx.is_nan() {
        let v_ptp = lnz_ptp(
            &mut rng, pr, &time_pf, &flux_t, sigma_t, p_orb, &star, n_draws, u1, u2,
        );
        pr.lnz.push(("_lnZ_PTP".to_string(), vec![v_ptp]));
        let (v_peb, v_pebx2) = lnz_peb(
            &mut rng, pr, &time_pf, &flux_t, sigma_t, p_orb, &star, n_draws, u1, u2,
        );
        pr.lnz.push(("_lnZ_PEB".to_string(), vec![v_peb, v_pebx2]));
        (v_ptp, v_peb, v_pebx2)
    } else {
        (f64::NEG_INFINITY, f64::NEG_INFINITY, f64::NEG_INFINITY)
    };

    // Nearby-star scenarios: up to 5 neighbours with tdepth > 0.
    let mut nearby_lnz: Vec<f64> = Vec::new();
    let neighbour_idx: Vec<usize> = (1..stars.len())
        .filter(|&i| stars[i].tdepth > 0.0)
        .take(5)
        .collect();
    for i in neighbour_idx {
        let ns = &stars[i];
        let ns_m = if ns.mass.is_nan() { 1.0 } else { ns.mass };
        let ns_r = if ns.rad.is_nan() { 1.0 } else { ns.rad };
        let ns_teff = if ns.teff.is_nan() { 5777.0 } else { ns.teff };
        let ns_logg = (G_CGS * ns_m * MSUN / npsum::libm_pow(ns_r * RSUN, 2.0)).log10();
        let (ns_u1, ns_u2) = stellar::get_ldc(ns_teff, ns_logg, 0.0);
        let (flux_ns, sigma_ns) = renorm_flux(&flux_pf, sigma, ns.fluxratio);
        probes.renorm.push((
            ns.fluxratio,
            sigma,
            flux_ns.iter().copied().take(8).collect(),
        ));
        let ns_star = StarParams {
            m_s: ns_m,
            r_s: ns_r,
            teff: ns_teff,
        };
        let ntp = lnz_ttp(
            &mut rng,
            pr,
            &time_pf,
            &flux_ns,
            sigma_ns,
            p_orb,
            &ns_star,
            n_draws / 2,
            ns_u1,
            ns_u2,
            0.0,
            false,
            Some("_lnZ_TTP"),
        );
        let (neb, neb_twin) = lnz_teb(
            &mut rng,
            pr,
            &time_pf,
            &flux_ns,
            sigma_ns,
            p_orb,
            &ns_star,
            n_draws / 2,
            ns_u1,
            ns_u2,
            0.0,
            false,
            Some("_lnZ_TEB"),
        );
        nearby_lnz.extend([ntp, neb, neb_twin]);
    }

    let mut all_lnz = vec![lnz_tp, lnz_eb, lnz_ebx2, lnz_ptp_v, lnz_peb_v, lnz_pebx2_v];
    all_lnz.extend(nearby_lnz);
    for v in all_lnz.iter_mut() {
        if !v.is_finite() {
            *v = f64::NEG_INFINITY;
        }
    }

    let finite: Vec<f64> = all_lnz
        .iter()
        .copied()
        .filter(|v| *v > f64::NEG_INFINITY)
        .collect();
    let max_lnz = if finite.is_empty() {
        0.0
    } else {
        finite.iter().copied().fold(f64::NEG_INFINITY, f64::max)
    };
    let mut probs: Vec<f64> = all_lnz.iter().map(|&v| (v - max_lnz).exp()).collect();
    let total = pairwise_sum(&probs);
    if total <= 0.0 {
        return None;
    }
    for p in probs.iter_mut() {
        *p /= total;
    }

    let p_tp = probs[0];
    let p_ptp = probs[3];
    let fpp = (1.0 - p_tp - p_ptp).clamp(0.0, 1.0);
    let nfpp = pairwise_sum(&probs[6..]).clamp(0.0, 1.0);

    Some(FppResult {
        fpp,
        nfpp,
        verdict: fpp_policy::verdict(fpp, Some(nfpp), high_crowding),
        high_crowding,
        gal_b: format!("{:.2}", gal_b).parse().unwrap_or(gal_b),
        n_nearby,
        trilegal_used,
    })
}
